insert into exam_sections(paper_id,type,item_count,position,status) select id,'reading_b',1,3,'published' from exam_papers where year=2025 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into reading_b_tasks(section_id,content,status) select s.id,'{"year":2025,"kind":"headings","title":"Five Steps to Suggesting a Change at Work That’ll Actually Get Taken Seriously","directions":"Read the following text and answer the questions by choosing the most suitable subheading from the list A–G for each of the numbered paragraphs (41–45). There are two extra subheadings which you do not need to use.","paragraphs":[{"text":"Everyone wants to be that person — the one who looks at the same information as everyone else, but who sees a fresh, innovative solution. However, it takes more than simply having a good idea. How you share it is as important as the suggestion itself."},{"text":"Why? Because writing a new script — literally or figuratively — means that other team members will have to adapt to something new. So whether you’re suggesting a (seemingly) benign change like streamlining outdated protocol, or a bigger change like adding an hour to each workday so people can leave early on Fridays, you’re asking others to reimagine their workflow or schedule. Not to mention, if the process you’re scrapping is one someone else suggested, there’s the possibility of hurt feelings."},{"text":"To gain buy-in on an innovative, new idea, follow these steps:"},{"text":"Great ideas don’t stand alone. In other words, you can’t mention your suggestion once and expect it to be adopted. To see a change, you’ll need to champion your plan and sell its merits. In addition, you need to be willing to stand up to scrutiny and criticism and be prepared to explain your innovation in different ways for various audiences.","number":41},{"text":"Sometimes it makes sense to go to your boss first. But other times, it’s useful to build a coalition among your co-workers or other stakeholders. When it works, it works great — because you’re ready for your stubborn supervisor’s pushback with answers like, “Actually, I connected with a few people in our tech department to discuss how much time these kinds of website updates would take, and they suggested they have the bandwidth.”","number":42},{"text":"One of the biggest barriers to gaining buy-in occurs when the owner of an idea is viewed as argumentative, defensive, or close-minded. Because, let’s be honest: No one likes a know-it-all. So, if people disagree with you, don’t be indignant. Instead, listen to their concerns fully, try to understand their perspective, and include their concerns (and possible remedies) in future discussions.","number":43},{"text":"So, instead of saying, “Martha, our current slogan is confusing and should be updated,” you could try, “Martha raises a great point that our current slogan has a long history for our stakeholders, but I wonder if we might be able to brainstorm a tagline that could build on that — and be clearer for new customers.”"},{"text":"New ideas are the grandchildren of old ones. In other words, don’t throw old solutions under the bus to make your improvement stand out. Remember that in light of whatever the problem the old system solved — or, maybe, has failed to solve in recent memory — it was a great idea at the time. Appreciating the older contributions as you suggest future innovations helps bolster the credibility of your idea.","number":44},{"text":"When pitching a new idea, it’s important to use the language of abundance instead of the language of deficit. Instead of saying what is wrong, broken, or suboptimal, talk about what is right, fixable, or ideal. For example, try, “I can see lots of applications for this new approach” rather than, “This innovation is the only way.” Be optimistic but realistic, and you will stand out.","number":45}],"options":[{"letter":"A","text":"Stay positive"},{"letter":"B","text":"Respect the past"},{"letter":"C","text":"Use channels"},{"letter":"D","text":"Give it time"},{"letter":"E","text":"Invite resistance"},{"letter":"F","text":"Be a salesman"},{"letter":"G","text":"Be humble"}],"questions":[{"number":41,"label":"Paragraph 41"},{"number":42,"label":"Paragraph 42"},{"number":43,"label":"Paragraph 43"},{"number":44,"label":"Paragraph 44"},{"number":45,"label":"Paragraph 45"}],"sourcePages":[11,12]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2025 and s.type='reading_b' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.reading_b_keys(task_id,keys) select t.id,'[{"number":41,"answer":"F","evidence":"champion your plan and sell its merits","explanation":"本段强调为建议争取支持并推销其优点，对应 salesman，而不是仅等待或保持积极。"},{"number":42,"answer":"C","evidence":"build a coalition among your co-workers or other stakeholders","explanation":"通过上司、同事和其他相关人员建立支持，重点是利用不同渠道，而非某个具体人。"},{"number":43,"answer":"G","evidence":"listen to their concerns fully","explanation":"面对反对意见应倾听、理解并吸收建议，体现谦逊，而非主动制造阻力。"},{"number":44,"answer":"B","evidence":"Appreciating the older contributions","explanation":"肯定旧方案在过去的贡献，不贬低过去，对应尊重过去。"},{"number":45,"answer":"A","evidence":"Be optimistic but realistic","explanation":"用积极的语言介绍新建议，乐观且务实，对应保持积极。"}]'::jsonb from reading_b_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2025 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'reading_b',1,3,'published' from exam_papers where year=2026 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into reading_b_tasks(section_id,content,status) select s.id,'{"year":2026,"kind":"matching","title":"","directions":"Read the following text and match each of the numbered items in the left column to its corresponding information in the right column. There are two extra choices in the right column.","paragraphs":[{"text":"In an effort to support restoration programmes, specialists are developing supplies of seeds and seedlings, maintaining gene banks and sequencing the genomes of indigenous trees and other crops. Their work deals with one of the problems that could block major restoration efforts in different parts of the world."},{"text":"“Where’s the planting material going to come from? That’s one big bottleneck,” says genetic-resources specialist Ramni Jamnadass."},{"text":"Asia is arguably the region most neglected by global efforts to increase diversity in restoration and to study native species. Christopher Kettle, Biodiversity International’s director for forest genetic resources and restoration in Rome, says that the need for infrastructure — things such as mechanisms for collecting and storing seeds, and nurseries to raise seedlings — might be most desperate here because many trees are ‘masting’ species, which don’t produce seeds every year. People need to be ready. “Otherwise, you miss the boat, you lose all the seed and you’ve got to wait another seven years,” says Kettle. “This is a really, really critical issue for restoration in Southeast Asia, because many of the most important timber species and tree species — the ones that will lock up the most carbon — they’re all masting species.”"},{"text":"Climate change is a driving factor in the push to restore forests, but it also raises questions, such as where trees can thrive in the future. Climate change is also expected to alter relationships between trees, insects, diseases and other forest species. “Insects that today are a minor problem may become a major problem if they can produce three or four generations in a year,” says forest ecologist John Stanturf. This remains a significant knowledge gap. “We know enough to know that this is a concern, but we don’t know enough about how to respond to it yet. That’s a great area to be doing research.” So is soil, says Cindy Prescott, a forest ecologist at the University of British Columbia in Vancouver. “If you don’t look at the soil at the start, you can spend a lot of money and time putting in species that aren’t going to survive there.”"},{"text":"With so much research left to do, leaders in the field have been doing some soul-searching, and acknowledging that restoration can be motivated by — and designed to meet — different needs. “When you talk about conservation or restoration, the first question has to be restoration by whom, for whom?” says Daniel Janzen, a biologist at the University of Pennsylvania."},{"text":"The question can have more than one answer. Much of the global funding for restoration is dedicated to developing it as a tool to mitigate climate change, notes restoration ecologist Pedro Brancalion. “But if you ask a farmer in Brazil if he or she is concerned about climate change, they would say, ‘No, I am concerned about water,’ ” he says. Their interests as stewards of the land need to be better integrated with those who have the money to support restoration."},{"text":"That has been the strongest lesson of all for forest ecologist Robin Chazdon. Restoration is about more than what gets planted in the ground, she says. “Yes, it’s about forests, but it’s really about people. They are the agents of restoration.”"}],"options":[{"letter":"A","text":"People must pay attention to the fact that some kinds of trees do not produce seeds annually."},{"letter":"B","text":"Soil is an important element to be taken into account in forest restoration."},{"letter":"C","text":"The purpose of restoration efforts may be different from the real needs of the people involved."},{"letter":"D","text":"Human factors, as well as trees planted, should be emphasized in forest restoration."},{"letter":"E","text":"The supply of seeds is a tough problem that has to be dealt with."},{"letter":"F","text":"When it comes to restoration, we have to stay with an awareness of whose interests to serve."},{"letter":"G","text":"Some creatures in the forest that multiply fast can become a great threat to forest restoration."}],"questions":[{"number":41,"label":"Ramni Jamnadass"},{"number":42,"label":"Christopher Kettle"},{"number":43,"label":"John Stanturf"},{"number":44,"label":"Pedro Brancalion"},{"number":45,"label":"Robin Chazdon"}],"sourcePages":[11,12]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2026 and s.type='reading_b' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.reading_b_keys(task_id,keys) select t.id,'[{"number":41,"answer":"E","evidence":"Where’s the planting material going to come from?","explanation":"Jamnadass 指出种植材料的来源是瓶颈，对应种子供应问题。"},{"number":42,"answer":"A","evidence":"many trees are ‘masting’ species, which don’t produce seeds every year","explanation":"Kettle 强调某些树种并非每年结籽，因此必须做好收集和储存准备。"},{"number":43,"answer":"G","evidence":"Insects that today are a minor problem may become a major problem","explanation":"Stanturf 指出昆虫繁殖加快可能让小问题变成严重威胁。"},{"number":44,"answer":"C","evidence":"Their interests as stewards of the land need to be better integrated","explanation":"Brancalion 用农民关注水而资助方关注气候的例子，指出恢复目标与当地真实需求可能不同。"},{"number":45,"answer":"D","evidence":"Yes, it’s about forests, but it’s really about people.","explanation":"Chazdon 强调恢复不只是种树，更关乎作为恢复行动主体的人。"}]'::jsonb from reading_b_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2026 on conflict(task_id) do update set keys=excluded.keys;
